/* GENERATED by tokens/build.mjs — do not edit. Values: docs/TOKENS.md. */

/* Raqt-only names. A host app has no utilities for these, so they have to be
   registered with Tailwind — but `reference` means registering only, no `:root`
   block of our own. The shadcn-standard names are deliberately absent: registering
   one replaces the host's entry for it and suppresses the host's own value, which
   would recolour their entire app. Those are retinted below instead. */
@theme reference {
  --color-warning: #FFA51F;
  --color-warning-foreground: #04120C;
  --color-success: #2BE07C;
  --color-success-foreground: #04120C;
  --color-info: #4FC3F7;
  --color-info-foreground: #06263A;
  --color-surface-1: #0E211A;
  --color-surface-2: #142E24;
  --color-surface-3: #1B3329;
  --color-status-upcoming: #142E24;
  --color-status-upcoming-foreground: #8AA79A;
  --color-status-live: #F04444;
  --color-status-live-foreground: #FFFFFF;
  --color-status-finished: #1B3329;
  --color-status-finished-foreground: #B4C9BF;
  --color-status-open: #08582D;
  --color-status-open-foreground: #5BE79F;
}

@utility shadow-e1 {
  box-shadow: var(--shadow-e1);
}

@utility shadow-e2 {
  box-shadow: var(--shadow-e2);
}

@utility shadow-e3 {
  box-shadow: var(--shadow-e3);
}

@utility font-display {
  font-family: var(--font-display);
  font-stretch: 115%;
  letter-spacing: -0.01em;
}

/* The scope. Custom properties declared on an element beat what it inherits, so
   `.raqt` always wins inside itself no matter what the host's `:root` says — and
   changes nothing outside itself. That asymmetry is the whole retrofit story. */
.raqt {
  --color-background: #071410;
  --color-foreground: #EAF5EF;
  --color-card: #0E211A;
  --color-card-foreground: #EAF5EF;
  --color-popover: #0E211A;
  --color-popover-foreground: #EAF5EF;
  --color-primary: #2BE07C;
  --color-primary-foreground: #04120C;
  --color-secondary: #142E24;
  --color-secondary-foreground: #EAF5EF;
  --color-muted: #142E24;
  --color-muted-foreground: #8AA79A;
  --color-accent: #1B3329;
  --color-accent-foreground: #EAF5EF;
  --color-destructive: #F04444;
  --color-destructive-foreground: #FFFFFF;
  --color-warning: #FFA51F;
  --color-warning-foreground: #04120C;
  --color-success: #2BE07C;
  --color-success-foreground: #04120C;
  --color-info: #4FC3F7;
  --color-info-foreground: #06263A;
  --color-border: #1B3329;
  --color-input: #2C5142;
  --color-ring: #2BE07C;
  --color-surface-1: #0E211A;
  --color-surface-2: #142E24;
  --color-surface-3: #1B3329;
  --color-status-upcoming: #142E24;
  --color-status-upcoming-foreground: #8AA79A;
  --color-status-live: #F04444;
  --color-status-live-foreground: #FFFFFF;
  --color-status-finished: #1B3329;
  --color-status-finished-foreground: #B4C9BF;
  --color-status-open: #08582D;
  --color-status-open-foreground: #5BE79F;
  --shadow-e1: none;
  --shadow-e2: none;
  --shadow-e3: none;
  --background: #071410;
  --foreground: #EAF5EF;
  --card: #0E211A;
  --card-foreground: #EAF5EF;
  --popover: #0E211A;
  --popover-foreground: #EAF5EF;
  --primary: #2BE07C;
