/* Only what actually differs. A token absent here — `--color-primary`, `--color-ring`
   — is one the contract holds identical across modes. */
.raqt.light,
.light .raqt {
  --color-background: #F2F7F4;
  --color-foreground: #071410;
  --color-card: #FFFFFF;
  --color-card-foreground: #071410;
  --color-popover: #FFFFFF;
  --color-popover-foreground: #071410;
  --color-secondary: #DCE7E1;
  --color-secondary-foreground: #071410;
  --color-muted: #E7EFEA;
  --color-muted-foreground: #5A736A;
  --color-accent: #DCE7E1;
  --color-accent-foreground: #071410;
  --color-destructive: #C42A2A;
  --color-warning: #D97F00;
  --color-warning-foreground: #FFFFFF;
  --color-success: #12A253;
