  --color-status-finished-foreground: #5A736A;
  --color-status-open: #C2F7DC;
  --color-status-open-foreground: #08582D;
  --shadow-e1: 0 1px 2px rgb(7 20 16 / 0.06);
  --shadow-e2: 0 2px 8px rgb(7 20 16 / 0.08);
  --shadow-e3: 0 8px 24px rgb(7 20 16 / 0.10);
  --background: #F2F7F4;
  --foreground: #071410;
  --card: #FFFFFF;
  --card-foreground: #071410;
  --popover: #FFFFFF;
  --popover-foreground: #071410;
  --secondary: #DCE7E1;
  --secondary-foreground: #071410;
  --muted: #E7EFEA;
  --muted-foreground: #5A736A;
  --accent: #DCE7E1;
  --accent-foreground: #071410;
  --destructive: #C42A2A;
  --border: #DCE7E1;
  --input: #B4C9BF;
}

@layer base {
  .raqt button:not(:disabled),
  .raqt [role="button"]:not(:disabled) {
    cursor: pointer;
  }
}
